// 依据本地 Stanford Shen 组网页快照生成候选；不据名单自动创建师承。
const fs=require('node:fs'),path=require('node:path'),{DatabaseSync}=require('node:sqlite');
const lines=new Map();for(let i=1;i<=5;i++){const raw=fs.readFileSync(path.join(__dirname,`StanfordShen校友-20261107-${i}.txt`),'utf8');for(const l of raw.split(/\r?\n/)){const m=l.match(/^L(\d+):\s*(.*)$/);if(m)lines.set(+m[1],m[2])}}
const norm=s=>s.normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/^Dr\.\s+/i,'').replace(/（[^）]*）|\([^)]*\)|—.*/g,'').toLowerCase().replace(/[^a-z ]+/g,' ').replace(/\s+/g,' ').trim();
const db=new DatabaseSync(path.join(__dirname,'检索队列.sqlite'),{readOnly:true}),records=db.prepare('SELECT id,name,unit,filename FROM records').all();db.close();const candidates=[];
for(const [n,t] of lines){const found=t.match(/^##\s+(?:Dr\.\s+)?(.+)$/);if(!found)continue;const a=norm(found[1]).split(' ');if(a.length<2)continue;const ctx=[];for(let k=n+1;k<=n+12;k++){let v=lines.get(k);if(v?.startsWith('## '))break;if(v)ctx.push(v)}const former=ctx.find(x=>/^Former:/i.test(x));if(!former)continue;for(const r of records){const b=norm(r.name).split(' ');if(b.length>=2&&a[0]===b[0]&&a.at(-1)===b.at(-1))candidates.push({record_id:r.id,name:r.name,unit:r.unit,filename:r.filename,listed_name:found[1],former,line:n,context:ctx.join(' ')})}}
const missing=[];for(let i=Math.min(...lines.keys());i<=Math.max(...lines.keys());i++)if(!lines.has(i))missing.push(i);
const out={source:'https://arpes.stanford.edu/our-people/previous-members',scope:'5 份已有快照的可读行，Former 角色字段',warning:'姓名匹配为候选；需核学位、时间、单位和研究方向，同名者容易误配；课题组关系不等于正式导师。',line_count:lines.size,missing_lines:missing,candidates};fs.writeFileSync(path.join(__dirname,'StanfordShen校友候选-20261108.json'),JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({line_count:lines.size,missing:missing.length,matches:candidates.length,candidates}));
